         "O5": "evals", "O6": "baseline", "O7": "immune_scan"}  # fmt: skip
MANIFESTS = ("pyproject.toml", "requirements.txt", "requirements-dev.txt", "setup.py",
             "setup.cfg", "Pipfile", "uv.lock", "poetry.lock")  # fmt: skip
